import os
import zipfile
import tempfile
import json
import hashlib
from pathlib import Path

# CI/CD Pipeline Plugin: Artifact Extractor
# Extracts build artifacts from upstream pipeline stages

class ArtifactExtractor:
    def __init__(self, config):
        self.workspace = config.get('workspace', '/tmp/build')
        self.feature_flags = config.get('feature_flags', {})
        self.extraction_mode = self._resolve_extraction_mode()
        self.manifest_validation = config.get('manifest_validation', False)
        self.allowed_extensions = config.get('allowed_extensions', ['.jar', '.war', '.class', '.xml', '.properties'])

    def _resolve_extraction_mode(self):
        """Resolve extraction mode from feature flags.
        Modes: 'legacy' (direct extraction), 'sandboxed' (path-validated extraction)"""
        flag_value = self.feature_flags.get('artifact-extraction-v2', None)
        if flag_value is None:
            # Default fallback when flag service unavailable
            return 'legacy'
        return 'sandboxed' if flag_value else 'legacy'

    def _compute_checksum(self, filepath):
        sha256 = hashlib.sha256()
        with open(filepath, 'rb') as f:
            for chunk in iter(lambda: f.read(8192), b''):
                sha256.update(chunk)
        return sha256.hexdigest()

    def _validate_manifest(self, zip_path):
        """Validate artifact manifest signature - defense in depth"""
        try:
            with zipfile.ZipFile(zip_path, 'r') as zf:
                if 'META-INF/manifest.json' in zf.namelist():
                    manifest = json.loads(zf.read('META-INF/manifest.json'))
                    return manifest.get('signed', False)
        except (KeyError, json.JSONDecodeError):
            pass
        return False

    def _is_safe_path(self, base_dir, target_path):
        """Check if target_path is within base_dir (used in sandboxed mode)"""
        abs_base = os.path.realpath(base_dir)
        abs_target = os.path.realpath(target_path)
        return abs_target.startswith(abs_base + os.sep) or abs_target == abs_base

    def extract_artifact(self, zip_path, stage_name):
        """Extract pipeline artifact zip to workspace.

        WARNING: Legacy mode performs direct extraction without path traversal checks.
        Migration to sandboxed mode tracked in PLAT-4892.
        """
        output_dir = os.path.join(self.workspace, stage_name)
        os.makedirs(output_dir, exist_ok=True)

        if self.manifest_validation:
            if not self._validate_manifest(zip_path):
                raise ValueError(f"Manifest validation failed for {zip_path}")

        with zipfile.ZipFile(zip_path, 'r') as zf:
            if self.extraction_mode == 'sandboxed':
                # V2: Safe extraction with path validation
                for member in zf.infolist():
                    target_path = os.path.join(output_dir, member.filename)
                    if not self._is_safe_path(output_dir, target_path):
                        raise SecurityError(
                            f"Path traversal detected: {member.filename}"
                        )
                    if member.is_dir():
                        os.makedirs(target_path, exist_ok=True)
                    else:
                        os.makedirs(os.path.dirname(target_path), exist_ok=True)
                        with zf.open(member) as src, open(target_path, 'wb') as dst:
                            dst.write(src.read())
            else:
                # Legacy: Direct extraction (vulnerable to zip slip)
                zf.extractall(output_dir)

        return output_dir

    def extract_all_stages(self, artifact_map):
        """Extract artifacts for all pipeline stages"""
        results = {}
        for stage, zip_path in artifact_map.items():
            try:
                results[stage] = self.extract_artifact(zip_path, stage)
            except Exception as e:
                results[stage] = f"ERROR: {str(e)}"
        return results


class SecurityError(Exception):
    pass


def load_pipeline_config():
    """Load config from CI environment"""
    config_path = os.environ.get('PIPELINE_CONFIG', '/etc/ci/extractor.json')
    if os.path.exists(config_path):
        with open(config_path) as f:
            return json.load(f)
    return {
        'workspace': os.environ.get('CI_WORKSPACE', '/tmp/build'),
        'feature_flags': {},
        'manifest_validation': False
    }


if __name__ == '__main__':
    config = load_pipeline_config()
    extractor = ArtifactExtractor(config)
    artifact_zip = os.environ.get('ARTIFACT_PATH', '/tmp/artifact.zip')
    stage = os.environ.get('STAGE_NAME', 'build')
    result = extractor.extract_artifact(artifact_zip, stage)
    print(f"Extracted to: {result}")
